// Extrae el contexto tenant del payload y normaliza variables.
// $env.* está bloqueado por N8N_BLOCK_ENV_ACCESS_IN_NODE, así que el
// fallback del callbackUrl va hardcoded a 127.0.0.1:8000. El backend
// puede sobreescribirlo enviando 'callbackUrl' explícitamente en el payload.
const d = $input.item.json;
const provider = (d.email_provider || 'outlook').toLowerCase();
return { json: {
  requestId: d.requestId || '',
  apiKey: d.apiKey || '',
  empresaId: d.empresaId || null,
  startDate: d.startDate || '',
  endDate: d.endDate || '',
  email: d.email || '',
  email_provider: provider,
  credential_email_id: d.credential_email_id || '',
  callbackUrl: d.callbackUrl || 'http://127.0.0.1:8000/api/asistente/callback/search-results'
}};

// Normaliza la salida de cualquiera de los 4 providers a un esquema único.
// Cada item de entrada es un correo; emitimos un item por cada adjunto PDF/ZIP.
const ctx = $('Extraer Contexto').item.json;
const results = [];

for (const item of $input.all()) {
  const email = item.json;
  let subject, from, date, attachments, messageId;

  // Outlook
  if (email.from?.emailAddress) {
    subject = email.subject || 'Sin asunto';
    from = email.from.emailAddress.address;
    date = email.receivedDateTime || '';
    attachments = email.attachments || [];
    messageId = email.id;
  }
  // Gmail
  else if (email.payload?.headers) {
    const headers = email.payload.headers || [];
    subject = headers.find(h => h.name === 'Subject')?.value || 'Sin asunto';
    from = headers.find(h => h.name === 'From')?.value || '';
    date = headers.find(h => h.name === 'Date')?.value || '';
    attachments = (email.payload.parts || []).filter(p => p.filename);
    messageId = email.id;
  }
  // IMAP (Yahoo/genérico) — n8n entrega .attachments en json directamente
  else {
    subject = email.subject || 'Sin asunto';
    from = email.from || '';
    date = email.date || '';
    attachments = email.attachments || [];
    messageId = email.uid || email.messageId || '';
  }

  for (const att of attachments) {
    const name = att.name || att.filename || 'archivo';
    const ext = name.split('.').pop()?.toLowerCase();
    if (ext === 'pdf' || ext === 'zip') {
      results.push({ json: {
        filename: name,
        size: att.size || att.contentBytes?.length || 0,
        date,
        sender: from,
        subject,
        contentType: att.contentType || att.mimeType || '',
        storage_path: name,
        messageId,
        attachmentId: att.id || att.attachmentId || '',
        sourceId: messageId + '::' + name
      }});
    }
  }
}

// Marcamos vacío si no hubo nada para que el siguiente IF lo detecte
if (results.length === 0) {
  return [{ json: { empty: true, ...ctx } }];
}
return results.map(r => ({ json: { ...r.json, ...ctx } }));
